-- ── LE CONTROLE ──
SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('PDR Cigars','Cuban Stock Cigar Co.','Blackbird Cigar Co.','Kafie 1901','Gran Habano','Cavalier Genève')) = 6 AS six_fiches,
  (SELECT `country_id` = 'dominican' FROM `brands` WHERE `name` = 'Kafie 1901') AS kafie_dominicaine,
  (SELECT `brands` LIKE '%PDR Cigars%' AND `brands` LIKE '%Kafie 1901%' FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT `brands` LIKE '%Gran Habano%' AND `brands` LIKE '%Cavalier Gen%' FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 209') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
